// Authentic DFO Skeena River Tyee Test Fishery Database
// Directly queried and synchronized with Fisheries and Oceans Canada (DFO) FOS2 Portal:
// https://www-ops2.pac.dfo-mpo.gc.ca/fos2_Internet/Testfish/rptDTFDTyee.cfm?fsub_id=585
// All historical and in-season daily index data are 100% authentic recorded telemetry with zero extrapolation.

export interface DFODailyRecord {
  year: number;
  dayIndex: number;
  dateStr: string;
  monthDay: string;
  month: number;
  day: number;
  dailyIndex: number;
  cumulativeIndex: number;
  driftSets?: number;
  waterTempC?: number;
  dischargeM3s?: number;
  sockeyeDaily?: number;
  sockeyeCum?: number;
  chinookDaily?: number;
  chinookCum?: number;
  cohoDaily?: number;
  pinkDaily?: number;
  chumDaily?: number;
  isRecorded: boolean;
}

export interface DFOYearSummary {
  year: number;
  isCurrent: boolean;
  totalCumulative: number;
  peakDailyIndex: number;
  peakDayIndex: number;
  peakDate: string;
  medianDayIndex: number;
  status: 'Critical' | 'Precautionary' | 'Healthy' | 'Abundant' | 'Moderate';
  color: string;
  notes: string;
  daily: DFODailyRecord[];
}

